import React, { useRef } from 'react';
import { ConfirmDialog, confirmDialog } from 'primereact/confirmdialog';
import { Toast } from 'primereact/toast';
import { Button } from 'primereact/button';

export default function Template() {
    const toast = useRef(null);

    const accept = () => {
        toast.current.show({ className: 'info', summary: 'Confirmed', detail: 'You have accepted', life: 3000 });
    };

    const reject = () => {
        toast.current.show({ className: 'warn', summary: 'Rejected', detail: 'You have rejected', life: 3000 });
    };

    const showTemplate = () => {
        confirmDialog({
            group: 'templating',
            header: 'Confirmation',
            message: (
                <div className="w-100p fvc fxb column gp3 bdr-primary">
                    <i className="pi pi-exclamation-circle font-size32 bold-font fg-primary"></i>
                    <span>Please confirm to proceed moving forward.</span>
                </div>
            ),
            accept,
            reject
        });
    };

    return (
        <>
            <Toast ref={toast} />
            <ConfirmDialog group="templating" />
            <div className="fxb fvc gp5">
                <Button onClick={() => showTemplate()} icon="pi pi-check" label="Confirm"></Button>
            </div>
        </>
    )

}